  "Résine durcie": "Hardened resin",
  "Butin de chasse, obtenu en Forêt ou au bâtiment Chasse.": "Hunting loot, found in the Forest or at the Hunting Lodge.",
  "Séchée au Séchoir (atelier de Chasse) à partir de Viande.": "Dried at the Drying Rack (Hunting Lodge workshop) from Meat.",
  "Récolté au bâtiment Champs.": "Harvested at the Fields.",
  "Coupé à la Scierie. Sert aux zones de production, aux planches et aux fondations du village.": "Cut at the Sawmill. Used for production zones, planks and the village's foundations.",
  "Extrait à la Mine. Sert aux zones de production et aux lingots de la Fonderie.": "Mined at the Mine. Used for production zones and the Foundry's ingots.",
  "Extraite à la Carrière. Sert aux zones de production, aux sillons irrigués et aux fondations du village.": "Quarried at the Quarry. Used for production zones, irrigated furrows and the village's foundations.",
  "Puisée au Puits — ressource la moins chère du village.": "Drawn from the Well — the village's cheapest resource.",
  "Eau filtrée à la Station de purification (atelier du Puits). Base de toutes les préparations de l'Apothicaire.": "Water filtered at the Purification Station (Well workshop). The base of every Apothecary brew.",
  "Fabriquée à partir de Bois.": "Made from Wood.",
  "Fabriqué à partir de Fer.": "Made from Iron.",
  "Pierre équarrie et cerclée de fer, à la Maçonnerie de la Carrière. Sert aux constructions du Désert.": "Stone squared and bound with iron, at the Quarry's Masonry. Used for buildings in the Desert.",
  "Lingot retravaillé à la Forge de la Mine. Sert à reforger l'équipement.": "Ingot reworked at the Mine's Forge. Used to reforge equipment.",
  "Moulue à partir de Blé.": "Ground from Wheat.",
  "Cuit à la Boulangerie (Champs) à partir d'Eau et de Farine.": "Baked at the Bakery (Fields) from Water and Flour.",
  "Repas au Campement : restaure 60 % des PV max. Vivres pour repartir au Désert (chasse, donjon, élite rejouée). Cuisine de camp : 3 Viandes séchées + 1 Pain.": "A meal at Camp: restores 60% of max HP. Provisions for setting out again in the Desert (hunt, dungeon, replayed elite). Camp Kitchen: 3 Dried meat + 1 Bread.",
  "Repas au Campement : restaure 35 % des PV max. Vivres pour repartir en Forêt (chasse, donjon, élite rejouée). Crafté à la Cuisine de camp à partir de Viande et d'Eau.": "A meal at Camp: restores 35% of max HP. Provisions for setting out again in the Forest (hunt, dungeon, replayed elite). Crafted at the Camp Kitchen from Meat and Water.",
  "Se remplit au Réservoir (Puits). Emportée dans un parcours du Désert, elle rend du Souffle une fois.": "Filled at the Reservoir (Well). Taken on a Desert route, it restores Breath once.",
  "Repas au Campement : restaure 100 % des PV max. Cuisine de camp (Chasse) : 1 Ration moyenne + 3 Sève d'Aeswyn → 1.": "A meal at Camp: restores 100% of max HP. Camp Kitchen (Hunting Lodge): 1 Medium ration + 3 Aeswyn Sap → 1.",
  "Résine runique rare, trouvée en Petite Aventure. Sert à cuisiner la Grande ration et, durcie à la Menuiserie, à bâtir les hauts paliers du village.": "Rare runic resin, found on Short Adventures. Used to cook the Large ration and, hardened at the Joinery, to build the village's high tiers.",
  "Sable fondu par la foudre, lisse comme de l'eau. Trouvé en Petite Aventure du Désert.": "Sand melted by lightning, smooth as water. Found on Desert Short Adventures.",
  "Une plaque arrachée au dard de la bête. Elle ne chauffe pas : elle boit le feu. On s'en sert pour les dernières reforges.": "A plate torn from the beast's sting. It doesn't heat up: it drinks the fire. Used for the last reforges.",
  "Verre des dunes chauffé deux fois au Tailleur de pierre. Il coupe le fer. Matériau des hauts paliers du village, au Désert.": "Dune glass heated twice at the Stonecutter. It cuts iron. Material for the village's high tiers, in the Desert.",
  "Sève d'Aeswyn durcie à la Menuiserie. Matériau de construction des hauts paliers du village, en Forêt enchantée.": "Aeswyn Sap hardened at the Joinery. Building material for the village's high tiers, in the Enchanted Forest.",
  "Se filtre à la Station de purification (Puits)": "Filtered at the Purification Station (Well)",
  "Se taille à la Maçonnerie (Carrière), avec de la Pierre et du Fer": "Cut at the Masonry (Quarry), from Stone and Iron",
