  "Le Dard des profondeurs (la bête sous la dune, carte du Désert)": "The Deep Sting (the beast under the dune, Desert map)",
  "Verre des dunes et Pierre chauffés au Tailleur de pierre (Carrière)": "Dune glass and Stone heated at the Stonecutter (Quarry)",
