  "Sanctuaire interdit": "Forbidden Sanctuary",
  "L'air est frais. Ce qui rôde à la Lisière ne dort jamais.": "The air is cool. Whatever prowls the Forest Edge never sleeps.",
  "Ici, la forêt ne chuchote plus : elle observe.": "Here, the forest no longer whispers: it watches.",
  "Le sable prend tout, et rend tard. Ce qui vit ici a le temps.": "The sand takes everything, and gives back late. What lives here has time.",
  "Sous le sable, des pierres taillées avant tout le reste. Elles n'ont pas fini d'attendre.": "Under the sand, stones cut before anything else. They haven't finished waiting.",
  "Un royaume est mort ici. Les pierres n'ont pas fini de tomber.": "A kingdom died here. The stones haven't finished falling.",
  "Les murs ont été écrits. Quelqu'un les relit encore.": "The walls were written on. Someone still reads them.",
  "Le froid entre. Il ne ressort pas.": "The cold comes in. It doesn't go out.",
  "Ici, on ne repose pas. On attend.": "Here, no one rests. They wait.",
  "La roche est chaude sous la main. Elle l'était déjà avant le feu.": "The rock is warm under your hand. It already was before the fire.",
  "La lave éclaire. Ce qu'elle éclaire est plus grand qu'il ne devrait.": "The lava gives light. What it lights is bigger than it should be.",
  "L'air a le goût de la nuit où le ciel s'est fendu.": "The air tastes of the night the sky split open.",
  "Le sommet. Ce n'est pas une fin.": "The summit. It isn't an end.",

