  "Dragon ancien": "Ancient Dragon",
  "Archimage": "Archmage",
  "Il a bu le fleuve pour ne pas mourir. Il a encore soif.": "He drank the river so as not to die. He's still thirsty.",

  // ELITE_DB
  "Fileuse aux yeux blancs": "White-Eyed Spinner",
  "Ronce qui se souvient": "The Bramble That Remembers",
  "Le Serment sous l'armure": "The Oath Under the Armour",
  "Le Dard des profondeurs": "The Deep Sting",
  "L'Arbre-mère": "The Mother Tree",
  "Ses yeux ont blanchi. Elle tisse toujours, mais plus rien ne se prend dans sa toile : on dirait qu'elle attend autre chose. Quelqu'un est passé par ici avant toi.": "Its eyes have turned white. It still spins, but nothing gets caught in its web any more: it seems to be waiting for something else. Someone came through here before you.",
  "Elle a poussé sur de la cendre, et la cendre ne l'a pas quittée. Quand on la coupe, elle chauffe au lieu de saigner.": "It grew on ash, and the ash never left it. When you cut it, it heats up instead of bleeding.",
  "L'armure est vide. Ce qui la tient debout n'est pas un homme : c'est une phrase, dite il y a longtemps à quelqu'un qui n'est jamais revenu l'en délier.": "The armour is empty. What keeps it standing isn't a man: it's a sentence, spoken long ago to someone who never came back to release it.",
  "La dune bouge avant lui. Quand le dard sort, l'eau des mares a déjà baissé : il boit d'abord, il frappe ensuite.": "The dune moves before it does. When the sting comes out, the water in the pools has already dropped: it drinks first, then it strikes.",
  "Ce n'est pas un arbre qui a poussé. C'est quelque chose qui a pris la forme d'un arbre pour qu'on cesse de le regarder. Le battement vient de dessous.": "It isn't a tree that grew. It's something that took the shape of a tree so that people would stop looking at it. The beating comes from underneath.",

