  "Tanière du Basilic": "Basilisk's Den",
  "Cité engloutie": "Sunken City",
  "Sanctuaire scellé": "Sealed Sanctuary",
  "Ossuaire": "Ossuary",
  "Gueule du volcan": "Volcano's Maw",
  "Sommet interdit": "Forbidden Summit",
  "Un antre reptilien tapi sous la roche, jusqu'au repaire du Basilic lui-même.": "A reptilian lair crouched under the rock, all the way to the Basilisk's own den.",
  "Ce que les ruines gardent encore, elles le gardent avec méthode.": "What the ruins still guard, they guard methodically.",
  "Les os y sont rangés. Pas tous.": "The bones are stored there. Not all of them.",
  "La montagne respire par ici. Chaud.": "The mountain breathes through here. Hot.",
  "Le sommet de la Tour, et ce qui s'y reflète.": "The top of the Tower, and what is reflected there.",
  "Les premières salles sentent la terre humide et la mousse. Des bruits de pas résonnent au loin — rien de bien effrayant, pour l'instant.": "The first rooms smell of damp earth and moss. Footsteps echo in the distance — nothing too frightening, for now.",
  "Un froid ancien s'infiltre jusque dans les os. Ces lieux ne sont pas laissés à l'abandon — quelque chose les garde, avec méthode.": "An ancient cold seeps right into your bones. This place hasn't been abandoned — something guards it, methodically.",
  "Les murs eux-mêmes semblent respirer. Peu de ceux qui s'aventurent ici en ressortent sans égratignures — et encore moins sans butin.": "The walls themselves seem to breathe. Few who venture here come out without scratches — and fewer still without loot.",
  "Le seuil du dernier palier. Une puissance oubliée sommeille dans l'obscurité — et elle sait déjà que tu es arrivé.": "The threshold of the last tier. A forgotten power slumbers in the dark — and it already knows you've arrived.",
