  "Le gardien de la Cité engloutie": "The Guardian of the Sunken City",
  "Ce qui dort sous les racines": "What Sleeps Under the Roots",
  "Le battement sous l'écorce": "The Beating Under the Bark",
  "Élite de la Forêt": "Forest Elite",
  "Élite du Désert": "Desert Elite",
  "Ça gargouille. Ça grossit. Ça ne pense qu'à une chose : toi.": "It gurgles. It swells. It thinks of only one thing: you.",
  "« Encore un qui croit que la forêt lui doit quelque chose. »": "“Another one who thinks the forest owes him something.”",
  "« Tu n'es pas celui que j'attends. Passe quand même, si tu peux. »": "“You're not the one I'm waiting for. Go through anyway, if you can.”",
  "Une odeur de terre mouillée, puis deux yeux jaunes qui ne clignent pas.": "A smell of wet earth, then two yellow eyes that don't blink.",
  "« Assez joué. »": "“Enough games.”",
  "« Soit. »": "“So be it.”",
  "Le Basilic siffle. Quelque chose répond dans l'ombre.": "The Basilisk hisses. Something answers in the dark.",
  "La masse s'affaisse et redevient une flaque. Une grosse flaque.": "The mass sags and becomes a puddle again. A big puddle.",
  "« La forêt… ne vous gardera pas. »": "“The forest… won't keep you.”",
  "Le sable coule de lui comme de l'eau.": "Sand pours out of him like water.",
  "Le sphinx se couche lentement, comme on se rassoit.": "The sphinx lies down slowly, the way one sits back down.",

