  // ADVENTURE_QUESTS
  "Prouver sa valeur": "Prove Your Worth",
  "Le Cœur de la Forêt": "The Heart of the Forest",
  "Premier sang": "First Blood",
  "Franchir la Lisière": "Cross the Forest Edge",
  "Tenir le Cœur": "Hold the Heart",
  "Ce qui tourne autour du camp": "What Circles the Camp",
  "Remonter à trois": "Climbing Out in Three",
  "La nuée": "The Swarm",
  "Le trône de sable": "The Sand Throne",
  "La Meute Affamée": "The Hungry Pack",
  "Les yeux blancs": "The White Eyes",
  "Ce qui a poussé sur la cendre": "What Grew on the Ash",
  "Le Roi Slime géant règne sur la Lisière depuis des lunes, gardant jalousement le passage vers le cœur de la forêt. Pour qu'on te laisse poursuivre, il faudra d'abord montrer que tu n'es pas qu'un simple aventurier de passage.": "The Giant Slime King has ruled the Forest Edge for moons, jealously guarding the way to the heart of the forest. Before you're allowed to go on, you'll first have to show you're not just another passing adventurer.",
  "Au-delà de la Lisière, l'air se fait plus lourd et les arbres plus anciens. Le Seigneur de guerre orc tient le Cœur : il faudra s'enfoncer, faire ses preuves, puis l'abattre pour que le passage vers le Désert s'ouvre.": "Beyond the Forest Edge, the air grows heavier and the trees older. The Orc Warlord holds the Heart: you'll have to push in, prove yourself, then bring him down for the way to the Desert to open.",
  "Les bêtes viennent flairer les braises. Écarte-les du feu, une à une.": "The beasts come to sniff at the embers. Drive them away from the fire, one by one.",
  "La Lisière d'un bout à l'autre, sans t'arrêter. Au bout, les marais. Ce qui les tient s'est relevé.": "The Forest Edge from end to end, without stopping. At the far end, the marshes. What holds them has risen again.",
  "Au Cœur, les bêtes arrivent plus vite qu'on ne décide. Dix d'affilée. Laisse le Grimoire frapper quand tu ne regardes pas.": "In the Heart, the beasts come faster than you can decide. Ten in a row. Let the Grimoire strike when you're not looking.",
  "Des loups rôdent près du campement. Il faut réduire leur nombre avant d'envisager d'installer un poste de chasse permanent.": "Wolves prowl near the camp. Their numbers need thinning before a permanent hunting post can be considered.",
  "Les toiles de la Lisière ne prennent plus rien. Elles pendent, intactes, comme si celle qui les a tissées avait cessé d'avoir faim. Wenna dit qu'elle a compté les fils deux fois et qu'il y en a trop.": "The webs of the Forest Edge no longer catch anything. They hang there, intact, as if the one who spun them had stopped being hungry. Wenna says she counted the threads twice and there are too many.",
  "Au Cœur, il y a un carré de terre où rien ne devrait tenir. Quelque chose y a poussé quand même. Brannoc y est allé une fois, il n'en parle pas.": "In the Heart, there's a patch of earth where nothing should take hold. Something grew there anyway. Brannoc went there once; he doesn't talk about it.",
  "le lit se remplit": "the riverbed fills",
  "il prend ta voix": "it takes your voice",
  "Vaincre {target} ennemis en Forêt": "Defeat {target} enemies in the Forest",
  "Vaincre le Roi Slime géant {target} fois": "Defeat the Giant Slime King {target} times",
  "Vaincre {target} ennemis en Cœur de la forêt": "Defeat {target} enemies in the Heart of the Forest",
  "Vaincre le Seigneur de guerre orc {target} fois": "Defeat the Orc Warlord {target} times",
  "Vaincre {target} ennemis à la Lisière": "Defeat {target} enemies at the Forest Edge",
  "Vaincre le Roi Slime géant": "Defeat the Giant Slime King",
  "Vaincre {target} ennemis au Cœur de la forêt": "Defeat {target} enemies in the Heart of the Forest",
  "Tuer {target} loups en Forêt": "Kill {target} wolves in the Forest",
  "Pister {target} araignées à la Lisière": "Track {target} spiders at the Forest Edge",
  "Vaincre la Fileuse aux yeux blancs": "Defeat the White-Eyed Spinner",
  "Pister {target} ronces au Cœur de la forêt": "Track {target} brambles in the Heart of the Forest",
  "Vaincre la Ronce qui se souvient": "Defeat the Bramble That Remembers",

  // HUNT_QUESTS
  "Chasse en Forêt": "Forest Hunt",
  "Ce que les bêtes ont bu": "What the Beasts Drank",
  "Battue en Forêt": "Forest Beat",
  "Battue du Désert": "Desert Beat",
  "Le gibier ne manque pas à la Lisière, et ce qu'il traîne avec lui non plus. Une bête abattue sur cinq ne laisse rien ; les autres rapportent viande, blé, bois, fer, pierre ou eau pour l'Entrepôt. Une chasse peut se répéter indéfiniment.": "There's no shortage of game at the Forest Edge, nor of what it drags along with it. One beast in five leaves nothing; the others bring back meat, wheat, wood, iron, stone or water for the Warehouse. A hunt can be repeated endlessly.",
  "Les bêtes du Cœur ne saignent pas comme les autres. Sous l'écorce de leur peau, quelque chose de clair affleure et durcit à l'air. La Forêt leur a donné quelque chose ; rien n'empêche de le reprendre.": "The beasts of the Heart don't bleed like the others. Under the bark of their hide, something clear rises and hardens in the air. The Forest gave them something; nothing stops you from taking it back.",
  "Aldric paie à la tête. Vingt bêtes, et la bourse s'ouvre — il ne demande ni laquelle, ni pourquoi. La Forêt en a toujours vingt de plus.": "Aldric pays by the head. Twenty beasts, and the purse opens — he doesn't ask which, or why. The Forest always has twenty more.",

