  "La porte du Temple": "The Temple Gate",
  "Les planches du pont sont neuves, quelqu'un les a changées cet hiver.": "The bridge planks are new; someone replaced them this winter.",
  "Des toiles tendues entre deux chênes, un feu qui ne fume presque pas.": "Canvas stretched between two oaks, a fire that barely smokes.",
  "L'eau est claire jusqu'au fond. Rien n'y bouge, ce qui n'est pas normal.": "The water is clear to the bottom. Nothing moves in it, which isn't normal.",
  "Neuf pierres debout. La dixième est couchée et personne ne se souvient l'avoir vue tomber.": "Nine standing stones. The tenth lies flat, and no one remembers seeing it fall.",
  "Une maison dans les branches, une échelle, une lanterne encore chaude.": "A house in the branches, a ladder, a lantern still warm.",
  "Des marches trop hautes pour des jambes humaines. En haut, une lueur.": "Steps too high for human legs. At the top, a glow.",
  "On l'entend avant de la voir. Un battement lent, sous l'écorce.": "You hear it before you see it. A slow beating, under the bark.",
  "Les fils vont d'un arbre à l'autre à hauteur de gorge.": "The threads run from tree to tree at throat height.",
  "Le sable entre les dalles ne vient pas d'ici.": "The sand between the flagstones doesn't come from here.",
  "La corde tient un usage de plus.": "The rope holds for one more use.",
  "Contrats de la Taverne : +10 % d'or.": "Tavern contracts: +10% gold.",
  "Puits +10 %.": "Well +10%.",
  "L'autel soigne aussi une blessure normale.": "The altar also heals a normal wound.",
  "Scierie +10 %.": "Sawmill +10%.",
  "Gourde : 40 Souffle au lieu de 25.": "Flask: 40 Breath instead of 25.",

