  "Le village hors du Cycle. Les trois secteurs de l'anneau 1 sont toujours à portée.": "The village outside the Cycle. The three sectors of ring 1 are always within reach.",
  "Touche un secteur pour voir ce qu'on en sait. Le Recouvrement ne reprend que ce qu'on lui laisse, quand une expédition échoue.": "Tap a sector to see what's known about it. The Reclaiming only takes back what it's left, when an expedition fails.",
