  "Chaque trouvaille : choisis 1 carte parmi 2.": "Each find: pick 1 card out of 2.",
  "À 0 PV, tu te relèves avec 40 % des PV.": "At 0 HP, you get back up with 40% HP.",
  "+1 cran sur la voie force et en chargeant.": "+1 step on the strength path and when charging.",
